BEGIN
  DECLARE period DATE DEFAULT DATE_TRUNC(CURRENT_DATE(), MONTH);
  DELETE FROM `northwind-analytics-demo.finance.trial_balance` WHERE report_date = period;
  INSERT INTO `northwind-analytics-demo.finance.trial_balance`
  SELECT period, account, SUM(amount), COUNT(*), CURRENT_TIMESTAMP()
  FROM `northwind-analytics-demo.finance.gl_entries`
  WHERE DATE_TRUNC(posted_on, MONTH) = period GROUP BY account;
END
